            break;
        }

        idx = m->items[*sel].extra;
        myvendor_sys_inbox_get(box, &nn, MYVENDOR_SYS_INBOX_MAX);
        if (idx >= nn) {
            break;
        }

        lv_pm_notify_show_ex(box[idx].title[0] ? box[idx].title : "通知",
                             box[idx].body[0] ? box[idx].body :
                             (box[idx].title[0] ? box[idx].title : "通知"),
                             box[idx].icon[0] ? box[idx].icon : NULL,
                             3000);
    }
    break;

    strncpy(buf, arg, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';

    title = buf;
    body = strchr(buf, '|');
    if (body == NULL) {
        lv_pm_notify_show_icon(NULL, buf, HELM_ICO_INBOX, 0);
        return;
    }

    *body++ = '\0';
    icon = strchr(body, '|');
    if (icon != NULL) {
        *icon++ = '\0';
    }

    if (title[0] == '\0') {
        title = NULL;
    }
    if (body[0] == '\0' && title != NULL) {
        body = title;
        title = NULL;
    }

    lv_pm_notify_show_ex(title, body,
        (icon != NULL && icon[0] != '\0') ? icon : NULL, 0);
