        bicycle_route_sim_set_speed(bicycle_config_nav_sim_speed_kph());
    }
    snprintf(msg, sizeof(msg), "Nav sim speed %.0f km/h",
        bicycle_config_nav_sim_speed_kph());
    lv_pm_bottom_show(msg, 0);
}

