    if (scene == NULL || scene[0] == '\0') {
        scene = "on";
    }

    for (unsigned i = 0u; desc == NULL && i < bicycle_demo_scene_count(); i++) {
        if (strcmp(bicycle_demo_scene_name(i), scene) == 0) {
            desc = bicycle_demo_scene_desc(i);
