 * @brief 返回 s 的 UTF-8 前缀长度：不超过 max_cols 个显示列（ASCII=1，CJK=2），
 *        且不切断多字节字符；非法/不完整序列按 1 字节处理并停止。
 */
static size_t bicycle_ui_ctl_utf8_prefix(const char * s, size_t max_cols)
{
    size_t n = 0u;
    size_t cols = 0u;

    if (s == NULL) {
        return 0u;
    }

    while (s[n] != '\0') {
        const unsigned char c = (unsigned char)s[n];
        size_t len;

        if (c < 0x80u) {
            len = 1u;
        } else if ((c & 0xE0u) == 0xC0u) {
            len = 2u;
        } else if ((c & 0xF0u) == 0xE0u) {
            len = 3u;
        } else if ((c & 0xF8u) == 0xF0u) {
            len = 4u;
        } else {
            break; /* 非法首字节：停止，避免把后续字节当字符 */
