        for (size_t i = 1u; i < len; i++) {
            if ((s[n + i] & 0xC0u) != 0x80u) {
                return n; /* 不完整/非法续字节：截到上一个完整字符 */
            }
        }
        if (cols + ((len == 1u) ? 1u : 2u) > max_cols) {
            break;
        }
        cols += (len == 1u) ? 1u : 2u;
        n += len;
    }

    return n;
}
