static uint32_t bicycle_ui_ctl_utf8_cp(const char * s, size_t len)
{
    const unsigned char * p = (const unsigned char *)s;

    switch (len) {
    case 2u:
        return ((uint32_t)(p[0] & 0x1Fu) << 6) | (uint32_t)(p[1] & 0x3Fu);
