void vmap_view_stamp_nav_then_track(vmap_view_t * view)
{
    stamp_overlays(view, false);
    if (view != NULL) {
        if (view->heading_up) {
            /* 屏上是 R、C 是隐藏的：直接作废 C 不会更新画面。这里走和
             * invalidate_canvas_area 同一条记账/限频/兜底路径。 */
            view->rot_pending = true;
            vmap_rot_service(view);
