/** 旋转模式下最多参与碰撞判定的候选（正立标签只有 8 个槽，取 2 倍即可）。 */
#define VMAP_ROT_PICK_MAX (VMAP_ROT_LABEL_MAX * 2)
/** 正立标签之间的最小空隙（px）。 */
#define VMAP_ROT_LABEL_GAP 4

typedef struct {
    int16_t idx;
    uint8_t tier;
    uint8_t prio;
    int32_t dist2;
    int32_t sx;
    int32_t sy;
} vmap_rot_pick_t;

static uint8_t vmap_rot_label_tier(uint8_t kind)
{
    if (kind == VMAP_LABEL_ROAD) {
        return 1u;
    }
    if (kind == VMAP_LABEL_POI) {
        return 2u;
    }
    return 0u;      /* PLACE / WATER 先放 */
}

/**
 * @brief 旋转标签的优先级：地名/水名 → 路名 → POI；同级近焦点的先放。
 */
static bool vmap_rot_pick_better(const vmap_rot_pick_t * a,
    const vmap_rot_pick_t * b)
{
    if (a->tier != b->tier) {
        return a->tier < b->tier;
    }
    if (a->prio != b->prio) {
        return a->prio > b->prio;
    }
    return a->dist2 < b->dist2;
}

static bool vmap_rot_boxes_overlap(const lv_area_t * a, const lv_area_t * b,
    int32_t gap)
{
    return a->x1 - gap <= b->x2 && a->x2 + gap >= b->x1
        && a->y1 - gap <= b->y2 && a->y2 + gap >= b->y1;
}
```

