        || !lv_font_get_glyph_dsc(font, &dc, (uint32_t)':', 0)) {
        return 0;
    }

    return (lv_coord_t)(((int32_t)d0.box_h - (int32_t)dc.box_h) / 2
        + ((int32_t)d0.ofs_y - (int32_t)dc.ofs_y));
}

