static void vmap_erase_baked_labels(vmap_view_t * view)
{
    vmap_blit_surface_t surf;
    int32_t i;

    if (view == NULL || view->cbuf == NULL
        || view->label_col.retained_count <= 0) {
        return;
    }

    surf.buf = view->cbuf;
    surf.w = view->w;
    surf.h = view->h;
    surf.stride = view->stride;

    for (i = 0; i < view->label_col.retained_count; i++) {
        const lv_area_t * box = &view->label_col.retained[i].box;
        const int32_t w = box->x2 - box->x1 + 1;
        const int32_t h = box->y2 - box->y1 + 1;

        if (w > 0 && h > 0) {
            (void)vmap_blit_fill(vmap_blit_get(), &surf,
                box->x1, box->y1, w, h, vmap_style_bg565());
        }
    }
    vmap_label_retained_reset(&view->label_col);
}

/**
