    }

    canvas.buf = (uint16_t *)view->cbuf;
    canvas.w = view->w;
    canvas.h = view->h;
    canvas.stride = view->stride;
    canvas.clip_n = 0;

    vmap_render_clear(&canvas, vmap_style_bg565());
    vmap_label_retained_reset(&view->label_col);
}

